using StackExchange.Redis;

public class StoreLocatorService
{
    private readonly IDatabase _db;
    private const string StoreKey = "stores:locations";

    public StoreLocatorService(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
    }

    public async Task AddStoreAsync(string storeId, double longitude, double latitude)
    {
        await _db.GeoAddAsync(StoreKey, longitude, latitude, storeId);
    }

    public async Task<IList<GeoResult>> FindNearbyAsync(double longitude, double latitude, double radiusKm, int count)
    {
        var results = await _db.GeoSearchAsync(
            StoreKey,
            longitude,
            latitude,
            radius: radiusKm,
            count: count,
            order: GeoOrder.Asc);

        return results.Select(r => new GeoResult
        {
            StoreId = r.Member!,
            DistanceKm = r.Distance.GetValueOrDefault().Kilometers
        }).ToList();
    }
}

public class GeoResult
{
    public string StoreId { get; set; } = string.Empty;
    public double DistanceKm { get; set; }
}

const Redis = require('ioredis');
const redis = new Redis();
const STORE_KEY = 'stores:locations';

async function addStore(storeId, longitude, latitude) {
  await redis.geoadd(STORE_KEY, longitude, latitude, storeId);
}

async function findNearby(longitude, latitude, radiusKm, count) {
  const results = await redis.geosearch(
    STORE_KEY,
    'FROMLONLAT', longitude, latitude,
    'BYRADIUS', radiusKm, 'km',
    'COUNT', count,
    'ASC',
    'WITHDIST'
  );

  return results.map(r => ({
    storeId: r.name,
    distanceKm: parseFloat(r.dist)
  }));
}

